text(await tools.exec_command({cmd:"@'
import json,pathlib,hashlib
r=pathlib.Path('.'); refs={}; summaries=[]
for name in ['caller-original-context','caller-reused-context']:
 d=json.loads((r/'work/asset-lineage'/f'{name}.json').read_text())
 for m in d['members']:
  l=m['lineage']; summaries.append({'surface':name,'candidate':m['candidate'],'sha256':m['sha256'],'status':l['provenance_status'],'jobs':[(j['id'],j['operation']) for j in l['jobs']]})
  for j in l['jobs']:
   a=j['journal']; p=r/a['uri']; b=p.read_bytes(); assert hashlib.sha256(b).hexdigest()==a['sha256']; z=json.loads(b); refs[a['uri']]=a['sha256']
   for ev in z.get('events',[]):
    e=ev.get('evidence',{}); q=e.get('response_path'); h=e.get('sha256')
    if q and h:
     b=(r/q).read_bytes(); assert hashlib.sha256(b).hexdigest()==h; json.loads(b); refs[q]=h
print(json.dumps(summaries,indent=2))
(r/'work/asset-lineage/caller-inspected-evidence.json').write_text(json.dumps({'refs':[{'path':p,'sha256':h} for p,h in refs.items()]},indent=2))
print('Fully parsed and verified journal/response files:',len(refs))
for p in refs:
 if '/jobs/' in p:
  z=json.loads((r/p).read_text()); req=z.get('intent',{}).get('request',{}); print(p, json.dumps({'tool':req.get('tool'),'arguments':req.get('arguments'),'events':[(e.get('event'),e.get('evidence',{}).get('provenance')) for e in z.get('events',[])]})[:3500])
